// Clocks from the 74.25 MHz reference, one 812.85 MHz VCO: system clock, SDRAM pin clock, SDRAM read
// capture clock, pixel 6.3504 MHz and its 90 degree copy, and a 33.8688 MHz scan clock for the capture clock's
// dynamic phase shift. The system clock is 101.6064 MHz (VCO / 8) or, in the SDRAM_135 variant, 135.4752 MHz (VCO / 6).
// The two PLLs are generated by tools/gen_pll.sh; docs/pocket/MEMTEST.md, "Clocks and pins" and "Calibration contract".
module pll_mem (
	input  wire refclk,
	input  wire rst,
	output wire clk_sys,
	output wire clk_sd,
	output wire clk_cap,        // moved in 1/8 VCO period steps by phase_en / updn (counter 2)
	output wire clk_vid,
	output wire clk_vid_90,
	output wire clk_scan,       // scanclk of the phase shift, system clock / 4 (/ 3 at 101.6064 MHz)
	output wire locked,
	input  wire phase_en,       // clk_scan domain
	input  wire updn,           // 1: delay clk_cap by one step
	output wire phase_done      // clk_scan domain
);

`ifdef SDRAM_135
	pll_mem_135 pll (
`else
	pll_mem_101 pll (
`endif
		.refclk     (refclk),
		.rst        (rst),
		.outclk_0   (clk_sys),
		.outclk_1   (clk_sd),
		.outclk_2   (clk_cap),
		.outclk_3   (clk_vid),
		.outclk_4   (clk_vid_90),
		.outclk_5   (clk_scan),
		.locked     (locked),
		.phase_en   (phase_en),
		.scanclk    (clk_scan),
		.updn       (updn),
		.cntsel     (5'd2),
		.phase_done (phase_done)
	);

endmodule
